import{_ as t,o,c as s,O as a}from"./chunks/framework.e0b066fe.js";const c="/Alan-blog/assets/websocket.565605b6.png",m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"study/websocket.md","filePath":"study/websocket.md","lastUpdated":1694189773000}'),p={name:"study/websocket.md"};function r(n,e,d,l,w,b){return o(),s("div",null,e[0]||(e[0]=[a('<h2 id="websocket" tabindex="-1">websocket <a class="header-anchor" href="#websocket" aria-label="Permalink to &quot;websocket&quot;">​</a></h2><p><a href="https://www.ruanyifeng.com/blog/2017/05/websocket.html" target="_blank" rel="noreferrer">https://www.ruanyifeng.com/blog/2017/05/websocket.html</a></p><p>其他特点包括：</p><p>（1）建立在 TCP 协议之上，服务器端的实现比较容易。</p><p>（2）与 HTTP 协议有着良好的兼容性。默认端口也是80和443，并且握手阶段采用 HTTP 协议，因此握手时不容易屏蔽，能通过各种 HTTP 代理服务器。</p><p>（3）数据格式比较轻量，性能开销小，通信高效。</p><p>（4）可以发送文本，也可以发送二进制数据。</p><p>（5）没有同源限制，客户端可以与任意服务器通信。</p><p>（6）协议标识符是<code>ws</code>（如果加密，则为<code>wss</code>），服务器网址就是 URL。</p><p><code>ws://example.com:80/some/path</code></p><p><img src="'+c+'" alt="websocket"></p>',11)]))}const k=t(p,[["render",r]]);export{m as __pageData,k as default};
